package com.renthub.favorite; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="RH_FAVORITES") public class Favorite{@Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="fav_seq") @SequenceGenerator(name="fav_seq",sequenceName="RH_FAVORITE_SEQ",allocationSize=1) private Long id; @Column(nullable=false) private Long userId; @Column(nullable=false,length=20) private String assetType; @Column(nullable=false) private Long assetId; @Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now(); public Long getId(){return id;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getAssetType(){return assetType;} public void setAssetType(String v){assetType=v;} public Long getAssetId(){return assetId;} public void setAssetId(Long v){assetId=v;}}
